{% extends "base.html" %}
{% block title %}加入夥伴簡介・BNI{{ chapter.name_zh }}{% endblock %}
{% block extra_style %}
  .join-wrap{max-width:560px;margin:0 auto;padding:64px 24px 100px;}
  .join-wrap h1{font-size:28px;font-weight:900;margin-bottom:8px;text-align:center;}
  .join-wrap .desc{text-align:center;color:var(--sub);font-size:15px;margin-bottom:32px;}
  .join-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:32px 28px;box-shadow:0 4px 16px rgba(0,0,0,.06);}
  .join-card label{display:block;font-size:14px;font-weight:700;color:var(--ink);margin:18px 0 6px;}
  .join-card label:first-of-type{margin-top:0;}
  .required{color:var(--red);}
  .join-card input[type=text],.join-card input[type=url],.join-card textarea{
    width:100%;padding:11px 14px;font-size:15px;border-radius:8px;border:1px solid var(--line);
    background:var(--paper);color:var(--ink);font-family:inherit;
  }
  .join-card textarea{resize:vertical;min-height:120px;line-height:1.6;}
  .join-card input[type=file]{width:100%;padding:10px 0;}
  .links-hint{font-size:13px;color:var(--sub);margin:24px 0 4px;}
  .link-row{display:flex;gap:8px;margin-top:8px;align-items:center;}
  .link-row input[type=url]{flex:1;min-width:0;}
  .edit-label-btn{
    width:auto;flex:0 0 auto;margin-top:0;padding:11px 12px;border:1px solid var(--line);border-radius:8px;
    background:transparent;color:var(--sub);font-size:13px;cursor:pointer;font-family:inherit;white-space:nowrap;
  }
  .edit-label-btn:hover{border-color:var(--red);color:var(--red);}
  .label-input{margin-top:6px;}
  .hint{font-size:13px;color:var(--sub);margin-top:6px;}
  .honeypot{position:absolute;left:-9999px;opacity:0;}
  .join-card button.submit-btn{
    width:100%;margin-top:28px;padding:14px;font-size:16px;font-weight:900;border:none;
    border-radius:8px;background:var(--red);color:#fff;cursor:pointer;font-family:inherit;
  }
  .join-card button.submit-btn:hover{background:var(--red-dark);}
  .error{margin-bottom:18px;padding:10px 12px;background:#FBEAEA;border:1px solid #E7B8B8;border-radius:8px;color:#A22026;font-size:14px;text-align:center;}
  .back{display:block;text-align:center;margin-top:20px;color:var(--sub);font-size:14px;}
{% endblock %}
{% block body %}
<div class="join-wrap">
  <h1>建立我的夥伴簡介</h1>
  <p class="desc">填寫您的資訊，送出後會立刻出現在BNI{{ chapter.name_zh }}頁面上</p>
  <div class="join-card">
    {% if error %}<div class="error">{{ error }}</div>{% endif %}
    <form method="POST" enctype="multipart/form-data">
      <input type="text" name="website" class="honeypot" tabindex="-1" autocomplete="off">

      <label>姓名 <span class="required">*</span></label>
      <input type="text" name="name" value="{{ form.get('name', '') }}" required>

      <label>公司 / 職稱 <span class="required">*</span></label>
      <input type="text" name="company_title" value="{{ form.get('company_title', '') }}" placeholder="例：OO顧問公司 執行長" required>

      <label>產業別／頭銜標籤（選填）</label>
      <input type="text" name="role_tag" value="{{ form.get('role_tag', '') }}" placeholder="例：財務顧問">

      <label>簡介 <span class="required">*</span></label>
      <textarea name="bio" required>{{ form.get('bio', '') }}</textarea>
      <div class="hint">可分段落，簡單介紹自己的專長與經歷</div>

      <label>照片 <span class="required">*</span></label>
      <input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required>
      <div class="hint">建議使用正面照，格式 jpg / png / webp</div>

      <div class="links-hint">以下連結都選填。內建按鈕文字就是平台名稱，不用理會就會這樣顯示；如果想改成別的文字，按「修改標籤」再輸入</div>

      {% set link_defs = [
        ('website_url', 'website_label', '官網', '官網', 'https://...'),
        ('fb_url', 'fb_label', 'FB 粉絲專頁', 'FB', 'https://facebook.com/...'),
        ('ig_url', 'ig_label', 'IG', 'IG', 'https://instagram.com/...'),
        ('threads_url', 'threads_label', 'Threads', 'Threads', 'https://threads.net/...'),
        ('youtube_url', 'youtube_label', 'YouTube', 'YouTube', 'https://youtube.com/...'),
        ('gjw_url', 'gjw_label', '乾淨世界 GJW', 'GJW', 'https://www.ganjing.world/...'),
        ('line_url', 'line_label', 'LINE', 'LINE', 'https://line.me/...'),
        ('podcast_url', 'podcast_label', 'Podcast', 'Podcast', 'https://...'),
        ('blog_url', 'blog_label', '部落格文章', '部落格', 'https://...'),
      ] %}
      {% for url_name, label_name, field_title, default_label, placeholder in link_defs %}
      {% set label_val = form.get(label_name, '') %}
      <label>{{ field_title }}</label>
      <div class="link-row">
        <input type="url" name="{{ url_name }}" value="{{ form.get(url_name, '') }}" placeholder="{{ placeholder }}">
        <button type="button" class="edit-label-btn" onclick="toggleLabelEdit(this)">修改標籤</button>
      </div>
      <input type="text" name="{{ label_name }}" value="{{ label_val }}" placeholder="{{ default_label }}"
        class="label-input" style="display:{{ 'block' if label_val else 'none' }}">
      {% endfor %}

      <button type="submit" class="submit-btn">送出</button>
    </form>
  </div>
  <a class="back" href="{{ url_for('chapter_page', slug=chapter.slug) }}">← 回BNI{{ chapter.name_zh }}頁面</a>
</div>
<script>
function toggleLabelEdit(btn) {
  var input = btn.parentElement.nextElementSibling;
  var showing = input.style.display === 'block';
  input.style.display = showing ? 'none' : 'block';
  if (!showing) input.focus();
}
</script>
{% endblock %}

