{% block body %}
<div class="join-wrap">
  <h1>修改我的資料</h1>
  <p class="desc">這是您的專屬編輯連結，只有您能看到並修改這份資料</p>
  <div class="join-card">
    {% if error %}<div class="error">{{ error }}</div>{% endif %}
    {% if saved %}<div class="saved">已儲存修改</div>{% endif %}
    <form method="POST" enctype="multipart/form-data">
      {% set f = form if form else member %}
      <label>姓名 <span class="required">*</span></label>
      <input type="text" name="name" value="{{ f.name if f else '' }}" required>

      <label>公司 / 職稱 <span class="required">*</span></label>
      <input type="text" name="company_title" value="{{ f.company_title if f else '' }}" required>

      <label>產業別／頭銜標籤（選填）</label>
      <input type="text" name="role_tag" value="{{ (f.role_tag if f else '') or '' }}">

      <label>簡介 <span class="required">*</span></label>
      <textarea name="bio" required>{{ f.bio if f else '' }}</textarea>

      <label>照片</label>
      <div class="current-photo"><img src="{{ url_for('static', filename='uploads/' ~ member.photo_filename) }}" alt="{{ member.name }}"></div>
      <div class="hint">不上傳新照片就會保留目前這張</div>
      <input type="file" name="photo" accept="image/jpeg,image/png,image/webp">

      <div class="links-hint">以下連結都選填。內建按鈕文字就是平台名稱，不用理會就會這樣顯示；如果想改成別的文字，按「修改標籤」再輸入</div>

      {% set link_defs = [
        ('website_url', 'website_label', '官網', '官網', 'https://...'),
        ('fb_url', 'fb_label', 'FB 粉絲專頁', 'FB', 'https://facebook.com/...'),
        ('ig_url', 'ig_label', 'IG', 'IG', 'https://instagram.com/...'),
        ('threads_url', 'threads_label', 'Threads', 'Threads', 'https://threads.net/...'),
        ('youtube_url', 'youtube_label', 'YouTube', 'YouTube', 'https://youtube.com/...'),
        ('gjw_url', 'gjw_label', '乾淨世界 GJW', 'GJW', 'https://www.ganjing.world/...'),
        ('line_url', 'line_label', 'LINE', 'LINE', 'https://line.me/...'),
        ('podcast_url', 'podcast_label', 'Podcast', 'Podcast', 'https://...'),
        ('blog_url', 'blog_label', '部落格文章', '部落格', 'https://...'),
      ] %}
      {% for url_name, label_name, field_title, default_label, placeholder in link_defs %}
      {% set label_val = (f[label_name] if f else '') or '' %}
      <label>{{ field_title }}</label>
      <div class="link-row">
        <input type="url" name="{{ url_name }}" value="{{ (f[url_name] if f else '') or '' }}" placeholder="{{ placeholder }}">
        <button type="button" class="edit-label-btn" onclick="toggleLabelEdit(this)">修改標籤</button>
      </div>
      <input type="text" name="{{ label_name }}" value="{{ label_val }}" placeholder="{{ default_label }}"
        class="label-input" style="display:{{ 'block' if label_val else 'none' }}">
      {% endfor %}

      <button type="submit" class="save-btn">儲存修改</button>
    </form>

    <div class="danger-zone">
      <p>不想再出現在分會頁面上？</p>
      <form method="POST" action="{{ url_for('member_join_edit_delete', slug=chapter.slug, token=token) }}"
        onsubmit="return confirm('確定要刪除您的簡介資料嗎？這個動作無法復原。');">
        <button type="submit" class="delete-btn">刪除我的資料</button>
      </form>
    </div>
  </div>
  <a class="back" href="{{ url_for('chapter_page', slug=chapter.slug) }}">← 回BNI{{ chapter.name_zh }}頁面</a>
</div>
<script>
function toggleLabelEdit(btn) {
  var input = btn.parentElement.nextElementSibling;
  var showing = input.style.display === 'block';
  input.style.display = showing ? 'none' : 'block';
  if (!showing) input.focus();
}
</script>
{% endblock %}

