function closeUsefulLinksModal(){
  document.getElementById('usefulLinksModal').classList.remove('open');
  document.body.style.overflow='';
}

function openMemberBio(btn){
  document.getElementById('memberModalName').textContent = btn.dataset.name;
  document.getElementById('memberModalSubtitle').textContent = btn.dataset.subtitle;
  var bioEl = document.getElementById('memberModalBio');
  bioEl.innerHTML = '';
  btn.dataset.bio.split(/\n\s*\n/).forEach(function(para){
    if (para.trim()) {
      var p = document.createElement('p');
      p.textContent = para.trim();
      bioEl.appendChild(p);
    }
  });
  var contactEl = document.getElementById('memberModalContact');
  contactEl.innerHTML = '';
  JSON.parse(btn.dataset.links || '[]').forEach(function(link){
    var a = document.createElement('a');
    a.href = link.url; a.target = '_blank'; a.rel = 'noopener'; a.textContent = link.label;
    contactEl.appendChild(a);
  });
  document.getElementById('memberBioModal').classList.add('open');
  document.body.style.overflow='hidden';
}
function closeMemberBio(){
  document.getElementById('memberBioModal').classList.remove('open');
  document.body.style.overflow='';
}
</script>

